// Digi's Epic Loot Add-ons: Epic Loot Storage Materials, Epic Loot Fixes, Enchant Glow Toggle, Shard Exclusivity,
// Set Pieces On Capes, Set Scanner, Socket Combine, Enchanting Layout.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiEpicLoot
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("randyknapp.mods.epicloot")]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.epiclootaddons";
        public const string Name = "Digi's Epic Loot Add-ons";
        public const string Version = "1.0.31";

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::EpicLootStorageMaterials.Plugin), "Epic Loot Storage Materials", "digi.valheim.epiclootstoragematerials", "The enchanting table uses materials, trophies and shardstones from nearby chests, and Store Nearby fills its Storage.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::EpicLootFixes.Plugin), "Epic Loot Fixes", "digi.valheim.epiclootfixes", "Damage enchantments that stack (switchable), Double and Triple Shot at a normal shot's cost, a Lucky Loot message, Lucky Loot on birds and a second chance at trophies.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::EnchantGlowToggle.Plugin), "Enchant Glow Toggle", "digi.valheim.enchantglowtoggle", "Hide or show enchantment glow and legendary looks, synced with friends.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::ShardExclusivity.Plugin), "Shard Exclusivity", "digi.valheim.shardexclusivity", "Shardstones can be socketed even when their effect normally clashes.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::SetPiecesOnCapes.Plugin), "Set Pieces On Capes", "digi.valheim.setpiecesoncapes", "A set's weapon or shield piece can also be a cape or backpack, in drops, enchanting and set runes.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::SetScanner.Plugin), "Set Scanner", "digi.valheim.setscanner", "A window (key J) with every Epic Loot set (which pieces you have nearby, which are missing, the set bonuses) and an Enchantments tab that finds every item nearby with an enchantment you search for.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::SocketCombine.Plugin), "Socket Combine", "digi.valheim.socketcombine", "A Combine tab at the enchanting table: two of the same item and rarity become one with one more shard socket (the one given up needs at least as many), up to its rarity's most, for coins and the rarity's essence, reagent and runestones.", new[] { "randyknapp.mods.epicloot" }, true),
            new ModuleInfo(typeof(global::EnchantingLayout.Plugin), "Enchanting Layout", "digi.valheim.enchantinglayout", "Epic Loot's enchanting window laid out evenly: its tabs split over both sides with their names, the frame wider; its screens untouched.", new[] { "randyknapp.mods.epicloot" }, true),
        };
    }
}
